import React from "react";
import ReactDOM from "react-dom/client";
import "bootstrap/dist/css/bootstrap.min.css";
import App from "./App";

ReactDOM.createRoot(document.getElementById("root")).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import { BrowserRouter, Routes, Route, NavLink, Navigate } from "react-router-dom";
import { Navbar, Nav, Container } from "react-bootstrap";
import PlantManagement from "./pages/PlantManagement";
import OrderManagement from "./pages/OrderManagement";
import EmployeeManager from "./pages/EmployeeManager";

function App() {
  return (
    <BrowserRouter>
      <Navbar bg="dark" variant="dark" expand="sm">
        <Container>
          <Navbar.Brand as={NavLink} to="/plants">Plant Shop</Navbar.Brand>
          <Nav>
            <Nav.Link as={NavLink} to="/employees">Employees (Q1)</Nav.Link>
            <Nav.Link as={NavLink} to="/plants">Plant Management</Nav.Link>
            <Nav.Link as={NavLink} to="/orders">Order Management</Nav.Link>
          </Nav>
        </Container>
      </Navbar>

      <Container className="my-4">
        <Routes>
          <Route path="/" element={<Navigate to="/plants" replace />} />
          <Route path="/plants" element={<PlantManagement />} />
          <Route path="/orders" element={<OrderManagement />} />
          <Route path="/employees" element={<EmployeeManager />} />
        </Routes>
      </Container>
    </BrowserRouter>
  );
}

export default App;

import axios from "axios";

// API BASE URL given by the paper
const api = axios.create({ baseURL: "http://localhost:9999" });
export default api;

export const employees = [
  { id: 1, fullName: "Vo An Hai", position: "Frontend Developer", department: "Software Engineering", salary: 1200, status: "Active" },
  { id: 2, fullName: "Le Hong Manh", position: "Backend Developer", department: "Software Engineering", salary: 1800, status: "Active" },
  { id: 3, fullName: "Nguyen Van Ty", position: "Tester", department: "Quality Assurance", salary: 1200, status: "Inactive" },
];

import { useState } from "react";
import { Container, Row, Col, Table, Card, Button, Badge } from "react-bootstrap";
import { employees } from "../data/employees";

function EmployeeManager() {
  // Selected employee shown in the detail area (null = nothing selected yet)
  const [selected, setSelected] = useState(null);

  return (
    <Container className="my-4">
      <Row>
        {/* 1.1 LEFT: Employee List */}
        <Col md={8}>
          <h4>Employee List</h4>
          <Table id="employee-table" striped bordered hover responsive>
            <thead>
              <tr>
                <th>ID</th><th>Full Name</th><th>Position</th>
                <th>Department</th><th>Salary</th><th>Status</th><th>Action</th>
              </tr>
            </thead>
            <tbody>
              {employees.map((e) => (
                <tr
                  key={e.id}
                  onClick={() => setSelected(e)}
                  id={`employee-row-${e.id}`}
                  className={`employee-row ${selected?.id === e.id ? "table-primary" : ""}`}
                  style={{ cursor: "pointer" }}
                >
                  <td>{e.id}</td>
                  <td>{e.fullName}</td>
                  <td>{e.position}</td>
                  <td>{e.department}</td>
                  <td>${e.salary}</td>
                  <td>
                    <Badge bg={e.status === "Active" ? "success" : "secondary"}>{e.status}</Badge>
                  </td>
                  <td>
                    <Button
                      size="sm"
                      variant="primary"
                      className="view-detail"
                      onClick={(ev) => { ev.stopPropagation(); setSelected(e); }}
                    >
                      View Detail
                    </Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </Table>
        </Col>

        {/* 1.2 RIGHT: Employee Detail (separate area) */}
        <Col md={4}>
          <h4>Employee Detail</h4>
          {selected ? (
            <Card id="employee-detail">
              <Card.Body>
                <Row className="g-2">
                  <Col xs={6}><b>ID:</b> {selected.id}</Col>
                  <Col xs={6}><b>Full Name:</b> {selected.fullName}</Col>
                  <Col xs={6}><b>Position:</b> {selected.position}</Col>
                  <Col xs={6}><b>Department:</b> {selected.department}</Col>
                  <Col xs={6}><b>Salary:</b> ${selected.salary}</Col>
                  <Col xs={6}><b>Status:</b> {selected.status}</Col>
                </Row>
              </Card.Body>
            </Card>
          ) : (
            <p className="text-muted detail-placeholder">Please select an employee.</p>
          )}
        </Col>
      </Row>
    </Container>
  );
}

export default EmployeeManager;

import { useState, useEffect } from "react";
import { Table, Form, Button, Row, Col, Alert } from "react-bootstrap";
import api from "../api";

const EMPTY = { name: "", price: "", category: "", stock: "" };

// 2.4 Plant validation (returns { field: message })
export function validatePlant(f) {
  const e = {};
  if (!String(f.name).trim()) e.name = "Name is required.";
  if (f.price === "" || !(Number(f.price) > 0)) e.price = "Price must be greater than 0.";
  if (!String(f.category).trim()) e.category = "Category is required.";
  if (f.stock === "" || !(Number(f.stock) >= 0)) e.stock = "Stock must be greater than or equal to 0.";
  return e;
}

function PlantManagement() {
  const [plants, setPlants] = useState([]);
  const [form, setForm] = useState(EMPTY);
  const [editingId, setEditingId] = useState(null);
  const [errors, setErrors] = useState({});
  const [message, setMessage] = useState("");

  // 2.1 fetch /plants
  const loadPlants = async () => {
    const res = await api.get("/plants");
    setPlants(res.data);
  };
  useEffect(() => { loadPlants(); }, []);

  const change = (field) => (e) => {
    const next = { ...form, [field]: e.target.value };
    setForm(next);
    // once an error is shown, re-check live so it disappears as soon as it is fixed
    if (errors[field]) setErrors(validatePlant(next));
  };

  // 2.2 Create / Update
  const handleSubmit = async (ev) => {
    ev.preventDefault();
    const e = validatePlant(form);
    setErrors(e);
    if (Object.keys(e).length) return;
    const payload = {
      name: form.name.trim(),
      price: Number(form.price),
      category: form.category.trim(),
      stock: Number(form.stock),
    };
    if (editingId) {
      await api.put(`/plants/${editingId}`, { ...payload, id: editingId });
      setMessage("Plant updated successfully.");
    } else {
      await api.post("/plants", payload);
      setMessage("Plant added successfully.");
    }
    setForm(EMPTY);
    setEditingId(null);
    loadPlants();
  };

  const handleEdit = (p) => {
    setForm({ name: p.name, price: String(p.price), category: p.category, stock: String(p.stock) });
    setEditingId(p.id);
    setErrors({});
  };

  const cancelEdit = () => { setForm(EMPTY); setEditingId(null); setErrors({}); };

  // 2.2 Delete
  const handleDelete = async (id) => {
    if (!window.confirm("Delete this plant?")) return;
    await api.delete(`/plants/${id}`);
    if (editingId === id) cancelEdit();
    setMessage("Plant deleted successfully.");
    loadPlants();
  };

  return (
    <div>
      <h3>Plant Management</h3>
      {message && (
        <Alert className="success-msg" variant="success" onClose={() => setMessage("")} dismissible>
          <i>{message}</i>
        </Alert>
      )}

      <h5>{editingId ? `Update Plant #${editingId}` : "Add Plant"}</h5>
      <Form noValidate onSubmit={handleSubmit} className="mb-4">
        <Row className="g-2 align-items-start">
          <Col md>
            <Form.Control id="plant-name" placeholder="Name" value={form.name} onChange={change("name")} isInvalid={!!errors.name} />
            <Form.Control.Feedback type="invalid">{errors.name}</Form.Control.Feedback>
          </Col>
          <Col md>
            <Form.Control id="plant-price" type="number" placeholder="Price" value={form.price} onChange={change("price")} isInvalid={!!errors.price} />
            <Form.Control.Feedback type="invalid">{errors.price}</Form.Control.Feedback>
          </Col>
          <Col md>
            <Form.Control id="plant-category" placeholder="Category" value={form.category} onChange={change("category")} isInvalid={!!errors.category} />
            <Form.Control.Feedback type="invalid">{errors.category}</Form.Control.Feedback>
          </Col>
          <Col md>
            <Form.Control id="plant-stock" type="number" placeholder="Stock" value={form.stock} onChange={change("stock")} isInvalid={!!errors.stock} />
            <Form.Control.Feedback type="invalid">{errors.stock}</Form.Control.Feedback>
          </Col>
          <Col md="auto">
            <Button id="plant-submit" type="submit">{editingId ? "Update Plant" : "Add Plant"}</Button>
            {editingId && (
              <Button variant="secondary" className="ms-2" onClick={cancelEdit}>Cancel</Button>
            )}
          </Col>
        </Row>
      </Form>

      <h5>Plant List</h5>
      <Table id="plant-table" striped bordered hover responsive>
        <thead>
          <tr>
            <th>ID</th><th>Name</th><th>Price</th><th>Category</th><th>Stock</th><th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {plants.map((p) => (
            <tr key={p.id} id={`plant-row-${p.id}`} className="plant-row">
              <td>{p.id}</td>
              <td>{p.name}</td>
              <td>{p.price}</td>
              <td>{p.category}</td>
              <td>{p.stock}</td>
              <td>
                <Button size="sm" variant="warning" className="me-2 edit-btn" onClick={() => handleEdit(p)}>Edit</Button>
                <Button size="sm" variant="danger" className="delete-btn" onClick={() => handleDelete(p.id)}>Delete</Button>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>
    </div>
  );
}

export default PlantManagement;

import { useState, useEffect } from "react";
import { Table, Form, Button, Row, Col, Alert } from "react-bootstrap";
import api from "../api";

const EMPTY = { customerName: "", plantId: "", quantity: "" };

function OrderManagement() {
  const [orders, setOrders] = useState([]);
  const [plants, setPlants] = useState([]);
  const [form, setForm] = useState(EMPTY);
  const [errors, setErrors] = useState({});
  const [message, setMessage] = useState("");

  const load = async () => {
    const [o, p] = await Promise.all([api.get("/orders"), api.get("/plants")]);
    setOrders(o.data);
    setPlants(p.data); // needed for the <select> and for the name mapping
  };
  useEffect(() => { load(); }, []);

  // 2.3 mapping plantId -> plant
  const findPlant = (id) => plants.find((x) => String(x.id) === String(id));

  // 2.4 Order validation (+ bonus: quantity must not exceed stock)
  const validate = (f) => {
    const e = {};
    if (!f.customerName.trim()) e.customerName = "Customer name is required.";
    if (!f.plantId) e.plantId = "Please select a plant.";
    if (f.quantity === "" || !(Number(f.quantity) > 0)) e.quantity = "Quantity must be greater than 0.";
    else {
      const p = findPlant(f.plantId);
      if (p && Number(f.quantity) > p.stock) e.quantity = `Quantity exceeds stock (only ${p.stock} left).`;
    }
    return e;
  };

  const change = (field) => (e) => {
    const next = { ...form, [field]: e.target.value };
    setForm(next);
    if (errors[field]) setErrors(validate(next));
  };

  const handleSubmit = async (ev) => {
    ev.preventDefault();
    const e = validate(form);
    setErrors(e);
    if (Object.keys(e).length) return;
    const plant = findPlant(form.plantId);
    const quantity = Number(form.quantity);
    await api.post("/orders", {
      customerName: form.customerName.trim(),
      plantId: plant.id, // keep the same type as plants.id
      quantity,
    });
    // bonus: reduce plant stock when an order is created
    await api.patch(`/plants/${plant.id}`, { stock: plant.stock - quantity });
    setForm(EMPTY);
    setMessage("Order added successfully.");
    load();
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Delete this order?")) return;
    await api.delete(`/orders/${id}`);
    setMessage("Order deleted successfully.");
    load();
  };

  return (
    <div>
      <h3>Order Management</h3>
      {message && (
        <Alert className="success-msg" variant="success" onClose={() => setMessage("")} dismissible>{message}</Alert>
      )}

      <h5>Add Order</h5>
      <Form noValidate onSubmit={handleSubmit} className="mb-4">
        <Row className="g-2 align-items-start">
          <Col md>
            <Form.Control id="order-customer" placeholder="Customer Name" value={form.customerName} onChange={change("customerName")} isInvalid={!!errors.customerName} />
            <Form.Control.Feedback type="invalid">{errors.customerName}</Form.Control.Feedback>
          </Col>
          <Col md>
            <Form.Select id="order-plant" value={form.plantId} onChange={change("plantId")} isInvalid={!!errors.plantId}>
              <option value="">-- Select Plant --</option>
              {plants.map((p) => (
                <option key={p.id} value={p.id}>{p.name} (stock: {p.stock})</option>
              ))}
            </Form.Select>
            <Form.Control.Feedback type="invalid">{errors.plantId}</Form.Control.Feedback>
          </Col>
          <Col md>
            <Form.Control id="order-quantity" type="number" placeholder="Quantity" value={form.quantity} onChange={change("quantity")} isInvalid={!!errors.quantity} />
            <Form.Control.Feedback type="invalid">{errors.quantity}</Form.Control.Feedback>
          </Col>
          <Col md="auto">
            <Button id="order-submit" type="submit">Add Order</Button>
          </Col>
        </Row>
      </Form>

      <h5>Order List</h5>
      <Table id="order-table" striped bordered hover responsive>
        <thead>
          <tr>
            <th>ID</th><th>Customer Name</th><th>Plant Name</th><th>Quantity</th><th>Total Price</th><th>Action</th>
          </tr>
        </thead>
        <tbody>
          {orders.map((o) => {
            const p = findPlant(o.plantId);
            return (
              <tr key={o.id} id={`order-row-${o.id}`} className="order-row">
                <td>{o.id}</td>
                <td>{o.customerName}</td>
                <td className="order-plant-name">{p ? p.name : "Unknown"}</td>
                <td>{o.quantity}</td>
                <td className="order-total">{p ? p.price * o.quantity : "-"}</td>
                <td>
                  <Button size="sm" variant="danger" className="order-delete" onClick={() => handleDelete(o.id)}>Delete</Button>
                </td>
              </tr>
            );
          })}
        </tbody>
      </Table>
    </div>
  );
}

export default OrderManagement;
